(()=>{'use strict';if(window.__qpuNewFromIqc)return;window.__qpuNewFromIqc=true;
const rows=x=>Array.isArray(x)?x:Array.isArray(x?.data)?x.data:[];
const val=(r,...keys)=>keys.map(k=>r?.[k]).find(v=>v!==undefined&&v!==null&&String(v).trim()!=='');
const date=v=>{const m=String(v||'').match(/^(20\d{2})-(\d{2})-(\d{2})/);return m?m[0]:''};
const minus7=d=>{const x=new Date(d+'T12:00:00Z');x.setUTCDate(x.getUTCDate()-7);return x.toISOString().slice(0,10)};
const safe=x=>String(x||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let inspections=[];
const dialog=document.createElement('div');dialog.id='qpu-new-iqc';dialog.hidden=true;dialog.innerHTML='<section><h3>신규 구매발주 등록 <button type="button" class="qni-close">×</button></h3><p>수입검사 입고일 기준 7일 전 발주일자 및 발주번호를 생성합니다. 기존 기록은 변경하지 않습니다.</p><label>수입검사 내역 <select class="qni-source"><option value="">수입검사 내역 불러오는 중</option></select></label><label>발주번호 <input class="qni-number" readonly placeholder="검사 선택 시 자동 발급"></label><label>발주일자 <input class="qni-date" type="date" title="실제 발주일자가 확인되면 수정하세요"></label><label>요청입고일 <input class="qni-receipt" readonly></label><label>공급업체 <input class="qni-supplier" readonly></label><label>품목명 <input class="qni-item" readonly></label><label>수량 <input class="qni-qty" type="number" min="0" step="any"></label><p class="qni-msg" aria-live="polite"></p><footer><button type="button" class="qni-cancel">취소</button><button type="button" class="qni-save">확인 후 등록</button></footer></section>';document.body.append(dialog);
const $=s=>dialog.querySelector(s);const close=()=>dialog.hidden=true;$('.qni-close').onclick=$('.qni-cancel').onclick=close;
function select(){const x=inspections[Number($('.qni-source').value)];if(!x)return;$('.qni-receipt').value=x.date;$('.qni-date').value=minus7(x.date);$('.qni-supplier').value=x.supplier;$('.qni-item').value=x.item;$('.qni-qty').value=x.qty||'';$('.qni-number').value='PO-'+minus7(x.date).replace(/-/g,'')+'-자동';$('.qni-msg').textContent='실제 발주일이 다른 경우 발주일자를 변경하세요. 저장 시 미사용 발주번호가 확정됩니다.'}
async function get(url,opts){const r=await fetch(url,{credentials:'include',cache:'no-store',...opts});const j=await r.json();if(!r.ok||j.success===false)throw Error(j.message||'요청 실패 '+r.status);return rows(j)}
async function open(){dialog.hidden=false;$('.qni-msg').textContent='수입검사 자료 조회 중';try{inspections=(await get('/api/iqc')).map(r=>({date:date(val(r,'date','inspectionDate','receiptDate')),supplier:String(val(r,'supplier','vendor')||''),item:String(val(r,'item','material')||''),qty:Number(val(r,'qty','quantity','receivedQty')||0),lot:String(val(r,'lot','materialLot')||'')})).filter(x=>x.date&&x.supplier&&x.item);$('.qni-source').innerHTML='<option value="">수입검사 내역 선택</option>'+inspections.map((x,i)=>'<option value="'+i+'">'+safe(x.date+' | '+x.supplier+' | '+x.item)+'</option>').join('');$('.qni-msg').textContent=inspections.length+'건 중 선택하세요.'}catch(e){$('.qni-msg').textContent='수입검사 조회 실패: '+e.message}}
$('.qni-source').onchange=select;$('.qni-date').onchange=()=>{$('.qni-number').value='PO-'+$('.qni-date').value.replace(/-/g,'')+'-자동'};
$('.qni-save').onclick=async()=>{const x=inspections[Number($('.qni-source').value)];if(!x||!$('.qni-source').value){$('.qni-msg').textContent='수입검사 기록을 선택하세요.';return}const qty=Number($('.qni-qty').value);if(!(qty>0)){ $('.qni-msg').textContent='발주수량을 확인하세요.';return}if(!confirm('선택한 수입검사 내역으로 실제 구매발주를 등록하시겠습니까?'))return;const btn=$('.qni-save');btn.disabled=true;try{const current=await get('/api/purchase-orders');const d=$('.qni-date').value||minus7(x.date),prefix='PO-'+d.replace(/-/g,'')+'-';const existing=new Set(current.map(p=>String(p.purchaseNo||p.id||'')));if(current.some(p=>p.supplier===x.supplier&&(p.item||p.material)===x.item&&(p.requestedDueDate||p.due)===x.date&&Number(p.qty)===qty&&(p.materialLot||p.lot||'')===x.lot))throw Error('같은 수입검사 내역으로 등록된 발주가 있습니다.');let n=1;while(existing.has(prefix+String(n).padStart(3,'0')))n++;const no=prefix+String(n).padStart(3,'0');if(!/^20\d{2}-\d{2}-\d{2}$/.test(d))throw Error('올바른 발주일자를 입력하세요.');const payload={purchaseNo:no,supplier:x.supplier,item:x.item,qty,unit:'kg',orderDate:d,requestedDueDate:x.date,confirmedDueDate:x.date,receiptDate:x.date,receivedQty:qty,receiptStatus:'입고완료',status:'완료',iqcStatus:'완료',materialLot:x.lot,notes:'수입검사 입고일 기준 발주 등록'};const res=await fetch('/api/purchase-orders',{method:'POST',headers:{'Content-Type':'application/json'},credentials:'include',body:JSON.stringify(payload)});const j=await res.json();if(!res.ok||j.success===false)throw Error(j.message||'저장 실패');$('.qni-number').value=no;$('.qni-msg').textContent=no+' 등록 완료. 구매발주 현황을 새로고침해 주세요.'}catch(e){$('.qni-msg').textContent='등록 실패: '+e.message}finally{btn.disabled=false}};
document.addEventListener('click',e=>{const b=e.target.closest?.('#purchase .new-btn');if(!b)return;e.preventDefault();e.stopImmediatePropagation();open()},true);
const css=document.createElement('style');css.textContent='#qpu-new-iqc[hidden]{display:none}#qpu-new-iqc{position:fixed;inset:0;z-index:99999;background:#14294266;display:flex;align-items:center;justify-content:center;padding:18px}#qpu-new-iqc section{background:white;border-radius:10px;max-height:94vh;overflow:auto;width:min(560px,96vw);padding:22px;box-shadow:0 18px 55px #1b2c4344}#qpu-new-iqc h3{color:#173b61;display:flex;justify-content:space-between;margin:0 0 12px}#qpu-new-iqc label{display:flex;align-items:center;gap:8px;margin:8px 0;font-size:12px}#qpu-new-iqc label input,#qpu-new-iqc label select{flex:1;min-width:0;padding:9px;border:1px solid #cbd8e5;border-radius:6px}#qpu-new-iqc footer{display:flex;justify-content:flex-end;gap:8px;margin-top:14px}#qpu-new-iqc button{padding:8px 12px;border:1px solid #cbd8e5;border-radius:6px;background:white;cursor:pointer}#qpu-new-iqc .qni-save{background:#166fbb;color:white}#qpu-new-iqc p{font-size:12px;color:#60738a}';document.head.append(css);
})();